// Locally bundled logos (generated by scripts/import-assets.py from the public asset library). Nothing is hot-linked: a logo is either
// shipped inside the extension or absent (callers then show their own fallback). The Trust Wallet token and trustwallet.com dApps are
// intentionally not bundled.
import tokenManifest from './tokenLogos.json';
import validatorManifest from './staking/validatorLogos.json';
import dappManifest from './discover/dappLogos.json';

const index = (m: Record<string, string[]>): Map<string, Map<string, string>> =>
  new Map(Object.entries(m).map(([chain, ids]) => [chain, new Map(ids.map((id) => [id.toLowerCase(), id]))]));
const tokens = index(tokenManifest as Record<string, string[]>);
const validators = index(validatorManifest as Record<string, string[]>);
const dapps = new Set(dappManifest as string[]);

/** Bundled logo of a token contract (EVM address, Solana mint, …) on a chain, or '' when none is bundled. */
export function tokenLogoPath(chain: string, address: string): string {
  const hit = tokens.get(chain)?.get(address.toLowerCase());
  return hit ? `/tokens/${chain}/${hit}.webp` : '';
}
/** Bundled logo of a staking validator, or '' when none is bundled. */
export function validatorLogoPath(chain: string, id: string): string {
  const hit = validators.get(chain)?.get(id.toLowerCase());
  return hit ? `/validators/${chain}/${hit}.webp` : '';
}
/** Bundled logo of a dApp, matched by the site's hostname (or a parent domain of it), or '' when none is bundled. */
export function dappLogoPath(url: string): string {
  let host = '';
  try { host = new URL(url).hostname.toLowerCase().replace(/^www\./, ''); } catch { return ''; }
  for (let h = host; h.includes('.'); h = h.slice(h.indexOf('.') + 1)) if (dapps.has(h)) return `/dapps/${h}.webp`;
  return '';
}
